01d4ae-\U0001d4b9\U0001d4bb\U0001d4bd-\U0001d4c3\U0001d4c5-\U0001d505\U0001d507-\U0001d50a\U0001d50d-\U0001d514\U0001d516-\U0001d51c\U0001d51e-\U0001d539\U0001d53b-\U0001d53e\U0001d540-\U0001d544\U0001d546\U0001d54a-\U0001d550\U0001d552-\U0001d6a5\U0001d6a8-\U0001d6c0\U0001d6c2-\U0001d6da\U0001d6dc-\U0001d6fa\U0001d6fc-\U0001d714\U0001d716-\U0001d734\U0001d736-\U0001d74e\U0001d750-\U0001d76e\U0001d770-\U0001d788\U0001d78a-\U0001d7a8\U0001d7aa-\U0001d7c2\U0001d7c4-\U0001d7cb\U0001d7ce-\U0001d7ff\U0001df00-\U0001df1e\U0001df25-\U0001df2a\U0001e030-\U0001e06d\U0001e100-\U0001e12c\U0001e137-\U0001e13d\U0001e140-\U0001e149\U0001e14e\U0001e290-\U0001e2ad\U0001e2c0-\U0001e2eb\U0001e2f0-\U0001e2f9\U0001e4d0-\U0001e4eb\U0001e4f0-\U0001e4f9\U0001e5d0-\U0001e5ed\U0001e5f0-\U0001e5fa\U0001e6c0-\U0001e6de\U0001e6e0-\U0001e6e2\U0001e6e4-\U0001e6e5\U0001e6e7-\U0001e6ed\U0001e6f0-\U0001e6f4\U0001e6fe-\U0001e6ff\U0001e7e0-\U0001e7e6\U0001e7e8-\U0001e7eb\U0001e7ed-\U0001e7ee\U0001e7f0-\U0001e7fe\U0001e800-\U0001e8c4\U0001e8c7-\U0001e8cf\U0001e900-\U0001e943\U0001e94b\U0001e950-\U0001e959\U0001ec71-\U0001ecab\U0001ecad-\U0001ecaf\U0001ecb1-\U0001ecb4\U0001ed01-\U0001ed2d\U0001ed2f-\U0001ed3d\U0001ee00-\U0001ee03\U0001ee05-\U0001ee1f\U0001ee21-\U0001ee22\U0001ee24\U0001ee27\U0001ee29-\U0001ee32\U0001ee34-\U0001ee37\U0001ee39\U0001ee3b\U0001ee42\U0001ee47\U0001ee49\U0001ee4b\U0001ee4d-\U0001ee4f\U0001ee51-\U0001ee52\U0001ee54\U0001ee57\U0001ee59\U0001ee5b\U0001ee5d\U0001ee5f\U0001ee61-\U0001ee62\U0001ee64\U0001ee67-\U0001ee6a\U0001ee6c-\U0001ee72\U0001ee74-\U0001ee77\U0001ee79-\U0001ee7c\U0001ee7e\U0001ee80-\U0001ee89\U0001ee8b-\U0001ee9b\U0001eea1-\U0001eea3\U0001eea5-\U0001eea9\U0001eeab-\U0001eebb\U0001f100-\U0001f10c\U0001fbf0-\U0001fbf9\U00020000-\U0002a6df\U0002a700-\U0002b81d\U0002b820-\U0002cead\U0002ceb0-\U0002ebe0\U0002ebf0-\U0002ee5d\U0002f800-\U0002fa1d\U00030000-\U0003134a\U00031350-\U00033479]{1,60}$' THEN RETURN false; END IF;
        END LOOP;
    END IF;
    IF k ? 'logo' AND k->'logo'<>'null'::jsonb THEN
        item:=k->'logo';
        IF jsonb_typeof(item)<>'object' OR item-ARRAY['projectId','assetId']<>'{}'::jsonb OR NOT item ?& ARRAY['projectId','assetId'] THEN RETURN false; END IF;
        IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(k->'assets') a WHERE a->'projectId'=item->'projectId' AND a->'assetId'=item->'assetId') THEN RETURN false; END IF;
    END IF;
    RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;
REVOKE ALL ON FUNCTION private.editor_brand_kit_valid(jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION private.read_editor_brand_kit(workspace uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE role text:=private.workspace_role(workspace); saved public.workspace_editor_brand_kits;
BEGIN
    IF role IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404';END IF;
    SELECT * INTO saved FROM public.workspace_editor_brand_kits WHERE workspace_id=workspace;
    -- Stored kits are returned as stored (a v1 kit stays v1) so an older client can still read and save it.
    -- 'v2' tells a newer client that this database accepts schema version 2.
    RETURN jsonb_build_object('kit',saved.kit,'version',coalesce(saved.version,0),'canEdit',role IN ('OWNER','ADMIN','CREATOR','EDITOR'),'v2',true);
END $$;
CREATE OR REPLACE FUNCTION private.save_editor_brand_kit(workspace uuid,expected integer,kit jsonb,request_key text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); head integer; payload jsonb; result jsonb; item jsonb; stored_kit jsonb; field text;
BEGIN
    IF coalesce(private.workspace_role(workspace),'') NOT IN ('OWNER','ADMIN','CREATOR','EDITOR') THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404';END IF;
    IF expected IS NULL OR expected<0 OR expected>=2147483647 OR jsonb_typeof(kit) IS DISTINCT FROM 'object' OR jsonb_typeof(kit->'assets') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE='PT400';END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(actor::text,85));PERFORM 1 FROM public.workspaces WHERE id=workspace FOR UPDATE;
    -- Recheck permissions after acquiring the resource lock, including soft deletion.
    IF coalesce(private.workspace_role(workspace),'') NOT IN ('OWNER','ADMIN','CREATOR','EDITOR') THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404';END IF;
    payload:=jsonb_build_object('workspace',workspace,'expected',expected,'kit',kit);result:=private.editor_request_probe('brand.save',request_key,payload);IF result IS NOT NULL THEN RETURN result;END IF;
    SELECT b.version,b.kit INTO head,stored_kit FROM public.workspace_editor_brand_kits b WHERE b.workspace_id=workspace;
    head:=coalesce(head,0);
    IF head<>expected THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='PT409';END IF;
    -- Preserve fields unknown to v1 clients (including mobile), but not an orphaned logo.
    -- The receipt payload above remains the original request, before this merge.
    FOREACH field IN ARRAY ARRAY['voice','hashtags'] LOOP
        IF NOT kit ? field AND stored_kit ? field THEN
            kit:=kit || jsonb_build_object(field,stored_kit->field);
        END IF;
    END LOOP;
    IF NOT kit ? 'logo' AND stored_kit ? 'logo' THEN
        kit:=kit || jsonb_build_object('logo',CASE WHEN EXISTS(
            SELECT 1 FROM jsonb_array_elements(kit->'assets') a
            WHERE a->'projectId'=stored_kit->'logo'->'projectId' AND a->'assetId'=stored_kit->'logo'->'assetId'
        ) THEN stored_kit->'logo' ELSE 'null'::jsonb END);
    END IF;
    IF NOT private.editor_brand_kit_valid(kit) THEN RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE='PT400';END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(kit->'assets') LOOP
        IF NOT EXISTS(SELECT 1 FROM public.project_assets a JOIN public.projects p ON p.id=a.project_id WHERE a.id=(item->>'assetId')::uuid AND p.id=(item->>'projectId')::uuid AND p.workspace_id=workspace AND a.state='inspected' AND private.project_role(p.id) IS NOT NULL) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404';END IF;
    END LOOP;
    IF kit->'logo' IS NOT NULL AND kit->'logo'<>'null'::jsonb AND NOT EXISTS(
        SELECT 1 FROM public.project_assets a JOIN public.projects p ON p.id=a.project_id
        WHERE a.id=(kit->'logo'->>'assetId')::uuid AND p.id=(kit->'logo'->>'projectId')::uuid
          AND p.workspace_id=workspace AND a.state='inspected' AND a.sniffed_type LIKE 'image/%'
          AND p.deleted_at IS NULL AND private.project_role(p.id) IS NOT NULL
    ) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404'; END IF;
    kit:=kit || jsonb_build_object('schemaVersion',2,'logo',coalesce(kit->'logo','null'::jsonb),'voice',coalesce(kit->'voice','""'::jsonb),
        'hashtags',coalesce((SELECT jsonb_agg(to_jsonb(regexp_replace(tag#>>'{}','^#','')) ORDER BY ord) FROM jsonb_array_elements(coalesce(kit->'hashtags','[]'::jsonb)) WITH ORDINALITY t(tag,ord)),'[]'::jsonb));
    IF octet_length(kit::text)>12288 THEN RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE='PT400'; END IF;
    INSERT INTO public.workspace_editor_brand_kits(workspace_id,version,kit,actor_id) VALUES(workspace,head+1,kit,actor) ON CONFLICT(workspace_id) DO UPDATE SET version=EXCLUDED.version,kit=EXCLUDED.kit,actor_id=EXCLUDED.actor_id,updated_at=now();
    result:=jsonb_build_object('kit',kit,'version',head+1,'canEdit',true,'idempotent',false,'v2',true);
    INSERT INTO private.editor_requests(actor_id,operation,key,payload,result) VALUES(actor,'brand.save',request_key,payload,result);RETURN result;
END $$;
-- Preserve the existing tenant JWT surface (ADR-0051); these replace existing functions.
REVOKE ALL ON FUNCTION private.read_editor_brand_kit(uuid),private.save_editor_brand_kit(uuid,integer,jsonb,text),public.read_editor_brand_kit(uuid),public.save_editor_brand_kit(uuid,integer,jsonb,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION private.read_editor_brand_kit(uuid),private.save_editor_brand_kit(uuid,integer,jsonb,text),public.read_editor_brand_kit(uuid),public.save_editor_brand_kit(uuid,integer,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_social_brand_kit(p_auth_id TEXT, p_brand_id UUID)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_role TEXT; v_link public.social_brand_kit_links; v_name TEXT; v_saved public.workspace_editor_brand_kits; v_can_link BOOLEAN; v_link_auth TEXT; v_extra JSONB;
BEGIN
    v_role := public.social_brand_role(p_auth_id, p_brand_id);
    IF v_role IS NULL THEN RETURN jsonb_build_object('ok',false,'code','BRAND_NOT_FOUND'); END IF;
    v_can_link := v_role = 'owner';
    -- The owner's picker lists only workspaces the link RPC will accept (editor-level roles).
    v_extra := CASE WHEN v_can_link THEN jsonb_build_object('workspaces',COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id',x.id,'name',x.name) ORDER BY x.name,x.id)
        FROM (SELECT w.id,w.name FROM public.workspaces w
              WHERE w.deleted_at IS NULL
                AND w.organisation_id IN (SELECT m.organisation_id FROM public.organisation_members m WHERE m.user_id = p_auth_id::uuid)
                AND coalesce(private.social_kit_workspace_role(p_auth_id::uuid,w.id),'') IN ('OWNER','ADMIN','CREATOR','EDITOR')
              ORDER BY w.name,w.id LIMIT 100) x),'[]'::jsonb)) ELSE '{}'::jsonb END;
    SELECT * INTO v_link FROM public.social_brand_kit_links WHERE brand_id = p_brand_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok',true,'linked',false,'canLink',v_can_link) || v_extra; END IF;
    SELECT u.auth_id INTO v_link_auth FROM public.users u WHERE u.id = v_link.linked_by AND u.deleted_at IS NULL;
    IF coalesce(private.social_kit_workspace_role(v_link_auth::uuid, v_link.workspace_id),'') NOT IN ('OWNER','ADMIN','CREATOR','EDITOR') THEN
        RETURN jsonb_build_object('ok',true,'linked',false,'stale',true,'canLink',v_can_link) || v_extra;
    END IF;
    SELECT w.name INTO v_name FROM public.workspaces w JOIN public.organisations o ON o.id = w.organisation_id
    WHERE w.id = v_link.workspace_id AND w.deleted_at IS NULL AND o.deleted_at IS NULL;
    IF v_name IS NULL THEN RETURN jsonb_build_object('ok',true,'linked',false,'stale',true,'canLink',v_can_link) || v_extra; END IF;
    SELECT * INTO v_saved FROM public.workspace_editor_brand_kits WHERE workspace_id = v_link.workspace_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('ok',true,'linked',true,'empty',true,'canLink',v_can_link) || v_extra
            || CASE WHEN v_can_link THEN jsonb_build_object('workspaceId',v_link.workspace_id,'workspaceName',v_name) ELSE '{}'::jsonb END;
    END IF;
    RETURN jsonb_build_object('ok',true,'linked',true,'empty',false,
        'canLink',v_can_link,'version',v_saved.version,
        'kit',jsonb_build_object(
            'voice',coalesce(v_saved.kit->'voice','""'::jsonb),'hashtags',coalesce(v_saved.kit->'hashtags','[]'::jsonb),
            'hasLogo',coalesce(v_saved.kit->'logo'<>'null'::jsonb,false),
            'name',v_saved.kit->'name','palette',v_saved.kit->'palette','fonts',v_saved.kit->'fonts','textStyles',v_saved.kit->'textStyles',
            'credits',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',a->'name','credit',a->'credit','usage',a->'usage','url',a->'url'))
                FROM jsonb_array_elements(v_saved.kit->'assets') a),'[]'::jsonb)))
        || CASE WHEN v_can_link THEN jsonb_build_object('workspaceId',v_link.workspace_id,'workspaceName',v_name) ELSE '{}'::jsonb END || v_extra;
END $$;

REVOKE ALL ON FUNCTION public.get_social_brand_kit(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_social_brand_kit(text,uuid) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;

